"""sklearn.feature_extraction.image — image patch / graph features."""

import numpy as _np


def extract_patches_2d(image, patch_size, *, max_patches=None, random_state=None):
    """Extract every ``patch_size`` window from a 2-D or 3-D image."""
    image = _np.asarray(image)
    if image.ndim == 2:
        image = image[:, :, None]
    H, W, C = image.shape
    ph, pw = patch_size
    rows = H - ph + 1
    cols = W - pw + 1
    patches = _np.zeros((rows * cols, ph, pw, C), dtype=image.dtype)
    idx = 0
    for i in range(rows):
        for j in range(cols):
            patches[idx] = image[i:i+ph, j:j+pw]; idx += 1
    if image.shape[2] == 1:
        patches = patches[..., 0]
    if max_patches is not None:
        rng = _np.random.default_rng(random_state if isinstance(random_state, int) else None)
        sel = rng.choice(len(patches), size=min(max_patches, len(patches)), replace=False)
        patches = patches[sel]
    return patches


def reconstruct_from_patches_2d(patches, image_size):
    """Reconstruct a 2-D image from overlapping patches by averaging."""
    H, W = image_size[:2]
    patches = _np.asarray(patches)
    if patches.ndim == 3:
        ph, pw = patches.shape[1:3]
        out = _np.zeros((H, W), dtype=float); count = _np.zeros((H, W))
    else:
        ph, pw, C = patches.shape[1:4]
        out = _np.zeros((H, W, C), dtype=float); count = _np.zeros((H, W, C))
    idx = 0
    for i in range(H - ph + 1):
        for j in range(W - pw + 1):
            out[i:i+ph, j:j+pw] += patches[idx]
            count[i:i+ph, j:j+pw] += 1
            idx += 1
    return out / _np.maximum(count, 1)


def grid_to_graph(n_x, n_y, n_z=1, *, mask=None, return_as=None, dtype=int):
    """Build an adjacency matrix for a regular 2-D/3-D voxel grid."""
    n = n_x * n_y * n_z
    A = _np.zeros((n, n), dtype=dtype)
    for i in range(n_x):
        for j in range(n_y):
            for k in range(n_z):
                idx = i * n_y * n_z + j * n_z + k
                for di, dj, dk in [(1,0,0), (0,1,0), (0,0,1)]:
                    ii, jj, kk = i+di, j+dj, k+dk
                    if 0 <= ii < n_x and 0 <= jj < n_y and 0 <= kk < n_z:
                        nidx = ii * n_y * n_z + jj * n_z + kk
                        A[idx, nidx] = A[nidx, idx] = 1
    return A


def img_to_graph(img, *, mask=None, return_as=None, dtype=None):
    """Build a graph from an image based on pixel intensity differences."""
    img = _np.asarray(img)
    H, W = img.shape[:2]
    n = H * W
    A = _np.zeros((n, n), dtype=float)
    for i in range(H):
        for j in range(W):
            idx = i * W + j
            for di, dj in [(0, 1), (1, 0)]:
                ii, jj = i+di, j+dj
                if ii < H and jj < W:
                    nidx = ii * W + jj
                    A[idx, nidx] = A[nidx, idx] = abs(float(img[i, j]) - float(img[ii, jj]))
    return A


class PatchExtractor:
    """Sklearn-style transformer wrapping :func:`extract_patches_2d`."""

    def __init__(self, *, patch_size=None, max_patches=None,
                  random_state=None):
        self.patch_size = patch_size
        self.max_patches = max_patches
        self.random_state = random_state

    def fit(self, X, y=None): return self

    def transform(self, X):
        patches = []
        for img in X:
            patches.append(extract_patches_2d(
                img, self.patch_size or (img.shape[0]//4, img.shape[1]//4),
                max_patches=self.max_patches,
                random_state=self.random_state))
        return _np.concatenate(patches) if patches else _np.empty((0,))
